#include <bits/stdc++.h>
using namespace std;

int findNext(vector<int>& parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];

    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> x(n), y(n), u(n), v(n);
    for (auto& value : x) cin >> value;
    for (auto& value : y) cin >> value;

    for (int i = 0; i < n; ++i) {
        u[i] = x[i] + y[i];
        v[i] = x[i] - y[i];
    }

    vector<int> orderU(n), orderV(n), rankU(n), rankV(n);
    iota(orderU.begin(), orderU.end(), 0);
    iota(orderV.begin(), orderV.end(), 0);

    sort(orderU.begin(), orderU.end(), [&](int a, int b) { return u[a] < u[b]; });
    sort(orderV.begin(), orderV.end(), [&](int a, int b) { return v[a] < v[b]; });

    for (int i = 0; i < n; ++i) {
        rankU[orderU[i]] = i;
        rankV[orderV[i]] = i;
    }

    long long minU = *min_element(u.begin(), u.end());
    long long maxU = *max_element(u.begin(), u.end());
    long long minV = *min_element(v.begin(), v.end());
    long long maxV = *max_element(v.begin(), v.end());

    vector<int> lowU(n), highU(n), lowV(n), highV(n);

    auto feasible = [&](long long d) {
        int left = 0, right = 0;
        for (int p : orderU) {
            while (left < n && u[orderU[left]] < u[p] - d) ++left;
            while (right < n && u[orderU[right]] <= u[p] + d) ++right;
            lowU[p] = left;
            highU[p] = right;
        }

        left = right = 0;
        for (int p : orderV) {
            while (left < n && v[orderV[left]] < v[p] - d) ++left;
            while (right < n && v[orderV[right]] <= v[p] + d) ++right;
            lowV[p] = left;
            highV[p] = right;
        }

        vector<int> nextU(n + 1), nextV(n + 1);
        iota(nextU.begin(), nextU.end(), 0);
        iota(nextV.begin(), nextV.end(), 0);

        vector<int> color(n, -1);
        vector<int> queue;
        queue.reserve(n);

        long long minColorU[2] = {LLONG_MAX, LLONG_MAX};
        long long maxColorU[2] = {LLONG_MIN, LLONG_MIN};
        long long minColorV[2] = {LLONG_MAX, LLONG_MAX};
        long long maxColorV[2] = {LLONG_MIN, LLONG_MIN};

        auto assign = [&](int p, int c) {
            color[p] = c;
            minColorU[c] = min(minColorU[c], u[p]);
            maxColorU[c] = max(maxColorU[c], u[p]);
            minColorV[c] = min(minColorV[c], v[p]);
            maxColorV[c] = max(maxColorV[c], v[p]);

            nextU[rankU[p]] = findNext(nextU, rankU[p] + 1);
            nextV[rankV[p]] = findNext(nextV, rankV[p] + 1);
            queue.push_back(p);
        };

        auto scanRange = [&](const vector<int>& order, vector<int>& next,
                             int l, int r, int targetColor) {
            int i = findNext(next, l);
            while (i < r) {
                int p = order[i];
                assign(p, targetColor);
                i = findNext(next, i);
            }
        };

        int root = 0;
        while (root < n) {
            while (root < n && color[root] != -1) ++root;
            if (root == n) break;

            queue.clear();
            assign(root, 0);

            for (size_t head = 0; head < queue.size(); ++head) {
                int p = queue[head];
                int c = color[p];

                if (minColorU[c] < u[p] - d || maxColorU[c] > u[p] + d ||
                    minColorV[c] < v[p] - d || maxColorV[c] > v[p] + d) {
                    return false;
                }

                int targetColor = 1 - c;
                scanRange(orderU, nextU, 0, lowU[p], targetColor);
                scanRange(orderU, nextU, highU[p], n, targetColor);
                scanRange(orderV, nextV, 0, lowV[p], targetColor);
                scanRange(orderV, nextV, highV[p], n, targetColor);
            }
        }

        return true;
    };

    long long low = -1;
    long long high = max(maxU - minU, maxV - minV);

    while (high - low > 1) {
        long long mid = low + (high - low) / 2;
        if (feasible(mid)) high = mid;
        else low = mid;
    }

    cout << high << '\n';
    return 0;
}
